      color: #94a3b8;
    }

    .stat-val {
      font-weight: 700;
      color: #00f2fe;
    }

    .controls-main {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      justify-content: center;
      align-items: center;
